/**
 * Run the forms submission browser test.
 *
 *   node tests/forms-submit-browser-test.js
 *
 * The page under test is generated by `tests/forms-submit-browser-fixture.php`
 * from the real renderer, and runs the plugin's real stylesheet and real
 * script. Only `window.fetch` is scripted: the challenge route and the
 * submission route answer with the exact bodies the plugin produces, so the
 * client's state machine — success, field errors, a stale page, a pending
 * attempt, a retry, a lost response, a double click and a failed provisioning —
 * is exercised end to end.
 *
 * A missing browser is a skip, not a pass. Set AGENTSHELL_REQUIRE_BROWSER=1 to
 * turn the skip into a failure — which is what CI does, because a skip is not a
 * test.
 *
 * Set AGENTSHELL_PHP to choose the PHP binary (default: `php`).
 */

'use strict';

var child_process = require( 'child_process' );
var fs = require( 'fs' );
var http = require( 'http' );
var os = require( 'os' );
var path = require( 'path' );

var CANDIDATES = [
    process.env.AGENTSHELL_BROWSER,
    'google-chrome',
    'google-chrome-stable',
    'chromium',
    'chromium-browser',
    'chrome',
];

function find_browser() {
    for ( var i = 0; i < CANDIDATES.length; i++ ) {
        var name = CANDIDATES[ i ];

        if ( ! name ) {
            continue;
        }

        try {
            var found = child_process.execFileSync( 'which', [ name ], { stdio: [ 'ignore', 'pipe', 'ignore' ] } );
            var path_found = found.toString().trim();

            if ( path_found ) {
                return path_found;
            }
        } catch ( e ) {
            // Not on PATH: try the next one.
        }
    }

    return null;
}

/**
 * The environment a browser child should start in.
 *
 * See `tests/forms-render-browser-test.js` for the full reasoning: with the
 * test bed's `LD_LIBRARY_PATH` exported (which the destructive suites need),
 * Chrome loads LocalWP's PHP libraries and dies before it renders. A browser is
 * not PHP and must not inherit PHP's private library path.
 *
 * @return {object} Environment for `execFile`.
 */
function browser_env() {
    var env = {};

    Object.keys( process.env ).forEach( function ( key ) {
        if ( 'LD_LIBRARY_PATH' !== key ) {
            env[ key ] = process.env[ key ];
        }
    } );

    return env;
}

function php_binary() {
    return process.env.AGENTSHELL_PHP || 'php';
}

function generate_page( out_file ) {
    var fixture = path.join( __dirname, 'forms-submit-browser-fixture.php' );

    if ( ! fs.existsSync( fixture ) ) {
        throw new Error( 'the fixture generator is missing: ' + fixture );
    }

    var output = child_process.execFileSync( php_binary(), [ fixture, out_file ], {
        stdio: [ 'ignore', 'pipe', 'pipe' ],
        maxBuffer: 16 * 1024 * 1024,
        timeout: 60000,
    } ).toString();

    if ( ! fs.existsSync( out_file ) ) {
        throw new Error( 'the fixture was not written: ' + output );
    }
}

/**
 * Serve the work directory over HTTP.
 *
 * `file://` has an opaque origin, so `sessionStorage` throws there — and the
 * stale-page recovery *uses* session storage to keep what the visitor typed.
 * A real origin is therefore not a convenience here: without it the behaviour
 * under test cannot exist.
 *
 * @param {string} dir Directory to serve.
 * @return {Promise<{url:string,close:Function}>}
 */
function start_server( dir ) {
    return new Promise( function ( resolve, reject ) {
        var server = http.createServer( function ( request, response ) {
            var name = decodeURIComponent( String( request.url || '/' ).split( '?' )[ 0 ] ).replace( /^\/+/, '' );
            var file = path.join( dir, name || 'fixture.html' );

            if ( -1 !== file.indexOf( '..' ) || ! fs.existsSync( file ) ) {
                response.writeHead( 404, { 'Content-Type': 'text/plain' } );
                response.end( 'not found' );
                return;
            }

            var body = fs.readFileSync( file );

            response.writeHead( 200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } );
            response.end( body );
        } );

        server.on( 'error', reject );

        server.listen( 0, '127.0.0.1', function () {
            var address = server.address();

            resolve( {
                url: 'http://127.0.0.1:' + address.port,
                close: function () {
                    // The browser keeps its connection alive, and `close()` waits
                    // for every connection to end. Ending them first is what
                    // lets the runner finish promptly.
                    if ( typeof server.closeAllConnections === 'function' ) {
                        server.closeAllConnections();
                    }

                    server.close();
                }
            } );
        } );
    } );
}

/**
 * Drive one scenario.
 *
 * The browser is spawned **asynchronously**: the page is served by this same
 * process, so blocking the event loop with `execFileSync()` would leave the
 * server unable to answer the browser's request and the two would wait for
 * each other until the timeout.
 *
 * @param {string} browser  Browser binary.
 * @param {string} url      Page URL.
 * @param {string} profile  Profile directory.
 * @param {string} scenario Scenario name.
 * @return {Promise<object>} The harness report.
 */
function run_scenario( browser, url, profile, scenario ) {
    var args = [
        '--headless',
        '--disable-gpu',
        '--no-sandbox',
        '--disable-dev-shm-usage',
        '--no-first-run',
        '--no-default-browser-check',
        '--force-prefers-reduced-motion',
        '--user-data-dir=' + profile,
        '--virtual-time-budget=30000',
        '--window-size=1280,900',
        '--dump-dom',
        url + '?scenario=' + scenario,
    ];

    return new Promise( function ( resolve, reject ) {
        child_process.execFile( browser, args, {
            maxBuffer: 64 * 1024 * 1024,
            timeout: 240000,
            encoding: 'utf8',
            env: browser_env(),
        }, function ( error, stdout ) {
            var output = String( stdout || '' );

            if ( error && ! output ) {
                reject( new Error( 'the browser did not run: ' + ( error.message || String( error ) ) ) );
                return;
            }

            var match = output.match( /<title>([\s\S]*?)<\/title>/ );

            if ( ! match ) {
                reject( new Error( 'the harness did not report a result' ) );
                return;
            }

            var title = match[ 1 ]
                .replace( /&quot;/g, '"' )
                .replace( /&#39;/g, "'" )
                .replace( /&lt;/g, '<' )
                .replace( /&gt;/g, '>' )
                .replace( /&amp;/g, '&' );

            var report;

            try {
                report = JSON.parse( title );
            } catch ( e ) {
                reject( new Error( 'the harness reported something that is not JSON: ' + title.slice( 0, 400 ) ) );
                return;
            }

            if ( report.harness_error ) {
                reject( new Error( 'the harness itself failed: ' + report.harness_error ) );
                return;
            }

            resolve( report );
        } );
    } );
}

async function main() {
    var browser = find_browser();

    if ( ! browser ) {
        var message = 'no browser found (looked for ' + CANDIDATES.filter( Boolean ).join( ', ' ) + ')';

        if ( process.env.AGENTSHELL_REQUIRE_BROWSER === '1' ) {
            console.error( 'FAIL the forms submission browser test needs a browser: ' + message );
            process.exit( 1 );
        }

        console.log( 'SKIP: ' + message );
        process.exit( 0 );
    }

    var work = fs.mkdtempSync( path.join( os.tmpdir(), 'agentshell-forms-submit-browser-' ) );
    var page = path.join( work, 'fixture.html' );
    var server = null;

    var scenarios = [];
    var failures = [];

    var names = [
        'ok',
        'errors',
        'stale',
        'stale_submit',
        'pending',
        'retry',
        'lost',
        'double',
        'challenge_fail'
    ];

    try {
        try {
            generate_page( page );
        } catch ( e ) {
            console.error( 'FAIL the page could not be generated: ' + ( e.message || e ) );
            process.exit( 1 );
        }

        try {
            server = await start_server( work );
        } catch ( e ) {
            console.error( 'FAIL the page could not be served: ' + ( e.message || e ) );
            process.exit( 1 );
        }

        for ( var index = 0; index < names.length; index++ ) {
            var name = names[ index ];
            var profile = path.join( work, 'profile-' + name );

            fs.mkdirSync( profile, { recursive: true } );

            var report = null;

            try {
                // Sequential, not parallel: each scenario gets its own profile
                // and its own virtual clock, and running them at once on a
                // small CI runner makes the timings meaningless.
                report = await run_scenario( browser, server.url + '/fixture.html', profile, name );
            } catch ( e ) {
                failures.push( { name: name + ': the browser reported', detail: ( e.message || String( e ) ).slice( 0, 500 ) } );
                continue;
            }

            scenarios.push( report );
            ( report.failures || [] ).forEach( function ( failure ) {
                failures.push( { name: name + ': ' + failure.name, detail: failure.detail } );
            } );

            if ( report.errors && report.errors.length ) {
                failures.push( { name: name + ': page errors', detail: report.errors.join( '; ' ) } );
            }
        }
    } finally {
        if ( server && typeof server.close === 'function' ) {
            try {
                server.close();
            } catch ( e ) {
                // Closing a server twice is not a test failure.
            }
        }

        try {
            fs.rmSync( work, { recursive: true, force: true } );
        } catch ( e ) {
            // A profile the browser still holds open is not a test failure.
        }
    }

    var total = scenarios.reduce( function ( sum, report ) { return sum + ( report.total || 0 ); }, 0 );

    failures.forEach( function ( failure ) {
        console.log( '  FAIL ' + failure.name + ( failure.detail === null || failure.detail === undefined ? '' : ' (' + failure.detail + ')' ) );
    } );

    var passed = Math.max( 0, total - failures.length );

    console.log( '  the page ran ' + total + ' browser assertions across ' + scenarios.length + ' submission scenarios' );
    console.log( '\n' + passed + ' passed, ' + failures.length + ' failed' );

    process.exit( failures.length > 0 ? 1 : 0 );
}

main();
